// --- AIPrompt ---

export const AIPrompt = forwardRef<HTMLDivElement, AIPromptProps>(
  ({ className, thinking, children, variant = "default", ...props }, ref) => {
    const theme = useTheme(),
      rootClasses = clsx(AIPromptClasses.root, className);

    return (
      <StyledAIPrompt
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        data-thinking={thinking}
        thinking={thinking}
        variant={variant}
        {...props}
      >
        {children}
      </StyledAIPrompt>
    );
  },
);
AIPrompt.displayName = "AI.Prompt";

// --- AIPromptContext ---

export const AIPromptContext = forwardRef<HTMLDivElement, AIPromptContextProps>(
  ({ className, children, ...props }, ref) => {
    const theme = useTheme();
    return (
      <div ref={ref} className={clsx(AIPromptClasses.context, className)}>
        <ChipBar
          selectionMode="none"
          styleSlots={{ root: { gap: theme.toRem(theme.spacing[4]) } }}
          {...(props as ChipBarProps)}
        >
          {children}
        </ChipBar>
      </div>
    );
  },
);
AIPromptContext.displayName = "AI.PromptContext";

// --- AIPromptInput ---

export const AIPromptInput = forwardRef<HTMLTextAreaElement, AIPromptInputProps>(
  (
    { className, value, onChange, onSubmit, placeholder = "Ask anything", disabled, ...props },
    ref,
  ) => {
    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        if (value?.trim()) {
          onSubmit?.(value);
        }
      }
    };

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      onChange?.(e.target.value);
    };

    return (
      <TextareaAutosize
        ref={ref}
        className={clsx(AIPromptClasses.input, className)}
        disabled={disabled}
        maxRows={10}
        minRows={1}
        placeholder={placeholder}
        value={value}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        {...props}
      />
    );
  },
);
AIPromptInput.displayName = "AI.PromptInput";

