AIPromptAttachmentMenuTrigger.displayName = "AI.PromptAttachmentMenuTrigger";

// --- AIPromptAttachmentMenu ---

export const AIPromptAttachmentMenu = forwardRef<HTMLDivElement, AIPromptAttachmentMenuProps>(
  ({ children, "aria-label": ariaLabel = "Add attachment", ...props }, ref) => {
    let trigger: React.ReactNode = null;
    const content: React.ReactNode[] = [];

    Children.forEach(children, (child) => {
      if (!isValidElement(child)) {
        content.push(child);
        return;
      }

      const type = child.type as { displayName?: string };
      const displayName = type?.displayName || "";
      // `.Trigger` suffix lets consumers compose with any *.Trigger subcomponent
      // (e.g., Menu.Trigger) without wrapping it in our own type.
      const isTrigger =
        displayName === "AI.PromptAttachmentMenuTrigger" || displayName.includes(".Trigger");

      if (isTrigger) {
        trigger = child;
      } else {
        content.push(child);
      }
    });

    return (
      <Menu ref={ref} {...props}>
        {trigger ? (
          <Menu.Trigger>{trigger}</Menu.Trigger>
        ) : (
          <Menu.Trigger>
            <AIPromptAttachmentMenuTrigger aria-label={ariaLabel} />
          </Menu.Trigger>
        )}
        <Menu.Content>{content}</Menu.Content>
      </Menu>
    );
  },
);
AIPromptAttachmentMenu.displayName = "AI.PromptAttachmentMenu";

interface AIPromptTaskBarContextValue {
  expanded: boolean;
  toggle: () => void;
  contentId: string;
}

const AIPromptTaskBarContext = createContext<AIPromptTaskBarContextValue | null>(null);

// eslint-disable-next-line react-refresh/only-export-components
export const useAIPromptTaskBarContext = () => {
  const context = useContext(AIPromptTaskBarContext);
  if (!context) {
    throw new Error("AIPromptTaskBar subcomponents must be used within AIPromptTaskBar");
  }
  return context;
};

export const AIPromptTaskBar = forwardRef<HTMLDivElement, AIPromptTaskBarProps>(
  (
    {
      className,
      children,
      expanded: expandedProp,
      defaultExpanded = false,
      onExpandChange,
      variant = "default",
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const [expandedState, setExpandedState] = useState(defaultExpanded);
    const isControlled = expandedProp !== undefined;
    const expanded = isControlled ? expandedProp : expandedState;
    const contentId = useId();

    const toggle = useCallback(() => {
      const newExpanded = !expanded;
      if (!isControlled) {
        setExpandedState(newExpanded);
      }
      onExpandChange?.(newExpanded);
    }, [expanded, isControlled, onExpandChange]);

    return (
      <AIPromptTaskBarContext.Provider value={{ expanded, toggle, contentId }}>
        <StyledAIPromptTaskBar
          ref={ref}
          className={clsx(AIPromptClasses.taskBar, className)}
          currentTheme={theme}
          data-expanded={expanded}
          variant={variant}
          {...props}
        >
          <div className={AIPromptClasses.taskBarPopup} data-expanded={expanded}>
            {children}
          </div>
        </StyledAIPromptTaskBar>
      </AIPromptTaskBarContext.Provider>
    );
  },
);

AIPromptTaskBar.displayName = "AI.PromptTaskBar";

export const AIPromptTaskBarHeader = forwardRef<HTMLDivElement, AIPromptTaskBarHeaderProps>(
  ({ className, children, ...props }, ref) => {
    const { expanded, toggle, contentId } = useAIPromptTaskBarContext();

    const handleKeyDown = useCallback(
      (e: React.KeyboardEvent<HTMLDivElement>) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          toggle();
        }
      },
      [toggle],
    );

    return (
      <div
        ref={ref}
        aria-controls={contentId}
        aria-expanded={expanded}
        className={clsx(AIPromptClasses.taskBarHeader, className)}
        role="button"
        tabIndex={0}
        onClick={toggle}
        onKeyDown={handleKeyDown}
        {...props}
      >
        <ChevronRight />
        <div>{children}</div>
      </div>
    );
  },
);

AIPromptTaskBarHeader.displayName = "AI.PromptTaskBarHeader";

export const AIPromptTaskBarContent = forwardRef<HTMLDivElement, AIPromptTaskBarContentProps>(
  ({ className, children, ...props }, ref) => {
    const { expanded, contentId } = useAIPromptTaskBarContext();

    return (
      <div
        ref={ref}
        aria-hidden={!expanded}
        className={clsx(AIPromptClasses.taskBarContent, className)}
        data-expanded={expanded}
        id={contentId}
        {...props}
      >
        <div className={AIPromptClasses.taskBarContentInner}>{children}</div>
      </div>
    );
  },
);

AIPromptTaskBarContent.displayName = "AI.PromptTaskBarContent";
